WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier, status ORDER BY shipped_date, id) AS row_num FROM shipments) x WHERE row_num = 1) SELECT CASE WHEN cost >= 95 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, SUM(CASE WHEN carrier = 'Kerry' THEN cost ELSE 0 END) AS kerry_cost, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END), 0), 2) AS cost_per_delivered, STDDEV_SAMP(cost) AS cost_stddev, COUNT(DISTINCT status) AS distinct_status FROM deduped GROUP BY CASE WHEN cost >= 95 THEN 'LARGE' ELSE 'SMALL' END HAVING ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END), 0), 2) < 0 ORDER BY cost_stddev;
